SELECT * FROM sp_tbl_ccp_generic_monitor_r_000(
    #{coCd, mode=IN, jdbcType=VARCHAR},
    #{docIdx, mode=IN, jdbcType=BIGINT}
)

SELECT d.doc_no AS ref_key, CASE d.status WHEN 'REQ' THEN '결재요청' WHEN 'REV' THEN '결재검토' WHEN 'APV' THEN '결재완료' ELSE d.status END AS target FROM tbl_document d JOIN tbl_ccp_generic_monitor m ON m.doc_idx = d.idx AND m.co_cd = d.co_cd WHERE d.co_cd = #{coCd} AND d.del_yn = 'N' AND d.status NOT IN ('TMP', 'RJT') AND d.idx IN
#{id}
ORDER BY d.doc_no LIMIT 1

